<!--
 * 系统配置管理页面 — 参数配置的分页列表、搜索、新增、编辑、删除
 *
 * @path apps\system-web\src\views\config\index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * 系统配置（列表页）
 * <p>消费后端契约 ConfigController（src/api/config.ts，auto-generated by bash/gen-contract.py）的系统配置列表页：
 * 分页查询 page、编辑/删除（remove）。
 * <p>集成列配置持久化：列可见性、列顺序、列宽度可自定义并在 localStorage 中持久化。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeTableGridOptions } from '@ydsz/plugins/vxe-table';

import { Page, useYdModal, YdConfirm } from '@ydsz/common-ui';
import { showToast } from '@ydsz/notification';

import { YdBadge, YdButton } from '@ydsz-core/ydsz-ui';
import { createLogger } from '@ydsz-core/shared/utils';
import { useTableColumnPreference } from '@ydsz-core/composables';
import { computed, h, ref, watch } from 'vue';
import { useI18n } from 'vue-i18n';

import { useAccess } from '@ydsz/access';

import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import { page, remove } from '#/api/config';
import type { ConfigPageQuery, ConfigVO, PageQuery } from '#/api/models';

import ConfigForm from './config-form.vue';
import ConfigHistoryDialog from './config-history-dialog.vue';

defineOptions({ name: 'ConfigManagement' });

/** 按钮级权限判断 + 数据范围（行级权限） */
const { hasAccessByCodesAll, getDataScope } = useAccess();

const logger = createLogger('system-config');

const { t } = useI18n();

/**
 * 数据范围（行级数据权限）。
 * - 资源类型标识: 'system:config'（系统配置）
 * - 返回值语义:
 *   - undefined: 未受限，可访问全部数据
 *   - 非空数组/对象: 受限，仅可访问指定范围
 * 由后端登录接口注入，当前仅做前端展示（后端 dataScope 过滤 TODO）。
 */
const dataScope = ref<unknown>(getDataScope('system:config'));

/** 数据范围展示标签（无约束时不渲染） */
const dataScopeLabel = computed(() => {
  const scope = dataScope.value;
  if (scope === undefined || scope === null) return '';
  if (Array.isArray(scope)) return `数据范围: 限定 ${scope.length} 项`;
  if (typeof scope === 'object') return '数据范围: 自定义约束';
  return `数据范围: ${String(scope)}`;
});

/** 行类型：真实契约 ConfigVO（字段以 models.ts 为准） */
type ConfigRow = ConfigVO;

/** 分页查询参数：契约 ConfigPageQuery + 通用分页字段（models.ts PageQuery） */
type ConfigPageQueryParams = ConfigPageQuery & PageQuery;

/** 状态是否启用（后端 status 为字符串，兼容 '1' / 'ENABLED' 两种取值） */
function isEnabled(status?: string): boolean {
  return status === '1' || status === 'ENABLED';
}

/* ===================== 列配置持久化 ===================== */

/**
 * 列配置面板的开关状态。
 */
const columnConfigOpen = ref(false);

/**
 * 列元信息：为持久化 composable 提供默认宽度与可见性。
 * 排序列（seq）和操作列（action）由表格特殊处理，不纳入持久化管理。
 */
const columnMetas = [
  { field: 'configKey', width: 180 },
  { field: 'configValue', width: 200 },
  { field: 'configGroup', width: 130 },
  { field: 'valueType', width: 100 },
  { field: 'isPublic', width: 70 },
  { field: 'status', width: 80 },
  { field: 'description', width: 180 },
];

const columnLabels: Record<string, () => string> = {
  configKey: () => t('configKey'),
  configValue: () => t('configValue'),
  configGroup: () => t('configGroup'),
  valueType: () => t('variable.valueType'),
  isPublic: () => t('isPublic'),
  status: () => t('status'),
  description: () => t('description'),
};

const {
  visibleColumns,
  columnOrder,
  columnWidth,
  setColumnVisible,
  setColumnWidth,
  resetToDefault,
} = useTableColumnPreference({
  tableId: 'system-config-list',
  columns: columnMetas,
  persist: true,
});

/**
 * 构建 vxe-grid 的 columns 配置，融合持久化的列可见性、顺序与宽度。
 *
 * <p>排序列（seq）和操作列（action）始终保留；其他列按 columnOrder 排序，
 * 仅渲染 columnPreferences.visibleColumns 中包含的列。
 */
const computedColumns = computed(() => {
  const visible = new Set(visibleColumns.value);

  // 构建字段 → 列配置的映射
  const fieldColumnMap: Record<string, NonNullable<VxeTableGridOptions<ConfigRow>['columns']>[number]> = {
    configKey: { field: 'configKey', title: t('configKey'), width: columnWidth.value.configKey ?? 180 },
    configValue: { field: 'configValue', title: t('configValue'), width: columnWidth.value.configValue ?? 200 },
    configGroup: { field: 'configGroup', title: t('configGroup'), width: columnWidth.value.configGroup ?? 130 },
    valueType: { field: 'valueType', title: t('variable.valueType'), width: columnWidth.value.valueType ?? 100 },
    isPublic: { field: 'isPublic', title: t('isPublic'), width: columnWidth.value.isPublic ?? 70 },
    status: {
      field: 'status',
      title: t('status'),
      width: columnWidth.value.status ?? 80,
      slots: {
        default: ({ row }: { row: ConfigRow }) => {
          return h(
            YdBadge,
            { variant: isEnabled(row.status) ? undefined : 'secondary' },
            () => (isEnabled(row.status) ? t('enabled') : t('disabled')),
          );
        },
      },
    },
    description: { field: 'description', title: t('description'), width: columnWidth.value.description ?? 180 },
  };

  // 按持久化顺序排列，过滤掉隐藏的列
  const ordered: NonNullable<VxeTableGridOptions<ConfigRow>['columns']> = [
    { type: 'seq', width: 50, title: t('seq') },
    ...columnOrder.value
      .filter((field: string) => visible.has(field) && !!fieldColumnMap[field])
      .map((field: string) => fieldColumnMap[field]!),
    {
      field: 'action',
      title: t('action'),
      width: 220,
      fixed: 'right' as const,
      slots: {
        default: ({ row }: { row: ConfigRow }) => {
          const buttons = [];
          // 编辑按钮 — 需要 sys:config:edit 权限
          if (hasAccessByCodesAll(['sys:config:edit'])) {
            buttons.push(h(YdButton, { size: 'sm', 'aria-label': `${t('edit')} - ${row.configKey ?? ''}`, onClick: () => handleEdit(row) }, () => t('edit')));
          }
          // 版本历史按钮 — 需要 sys:config:edit 权限
          if (hasAccessByCodesAll(['sys:config:edit'])) {
            buttons.push(h(YdButton, { size: 'sm', variant: 'destructive', 'aria-label': `${t('configVersion.history')} - ${row.configKey ?? ''}`, onClick: () => handleVersionHistory(row) }, () => t('configVersion.history')));
          }
          // 删除按钮 — 需要 sys:config:delete 权限
          if (hasAccessByCodesAll(['sys:config:delete'])) {
            buttons.push(h(YdButton, { size: 'sm', variant: 'destructive', 'aria-label': `${t('delete')} - ${row.configKey ?? ''}`, onClick: () => handleDelete(row) }, () => t('delete')));
          }
          return h('div', { class: 'flex gap-1' }, buttons);
        },
      },
    },
  ];

  return ordered;
});

const gridOptions = computed<VxeTableGridOptions<ConfigRow>>(() => ({
  columns: computedColumns.value,
  height: 'auto',
  pagerConfig: { pageSize: 20, pageSizes: [10, 20, 50, 100] },
  proxyConfig: {
    ajax: {
      query: async ({ page: pageInfo }, formValues) => {
        const query: ConfigPageQueryParams = {
          pageNum: pageInfo.currentPage,
          pageSize: pageInfo.pageSize,
          ...formValues,
        };
        const res = await page({ query });
        return { items: res.data ?? [], total: res.total ?? 0 };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, search: true, zoom: true },
  formConfig: {
    enabled: true,
    items: [
      { field: 'configKey', title: t('configKey'), itemRender: { name: 'YdInput', props: { placeholder: t('configKey') } } },
      { field: 'configGroup', title: t('configGroup'), itemRender: { name: 'YdInput', props: { placeholder: t('configGroup') } } },
    ],
  },
}));

const [Grid, gridApi] = useYDSZVxeGrid({ gridOptions: gridOptions.value as Record<string, unknown> });

// 列配置变更后同步到 grid
watch(gridOptions, (opts) => {
  gridApi.setGridOptions({ columns: opts.columns });
});

const [ConfigFormModal, configFormApi] = useYdModal({ connectedComponent: ConfigForm });

/** 版本历史抽屉引用 */
const historyDialogRef = ref<InstanceType<typeof ConfigHistoryDialog>>();

function handleAdd() {
  configFormApi.open();
}

function handleEdit(row: ConfigRow) {
  configFormApi.setData({ record: row });
  configFormApi.open();
}

function handleVersionHistory(row: ConfigRow) {
  historyDialogRef.value?.open(row.configKey ?? '');
}

async function handleDelete(row: ConfigRow) {
  // 步骤1：确认弹窗（用户取消直接返回）
  try {
    await YdConfirm(t('confirmDeleteName', [row.configKey ?? '']), t('common.deleteConfirm'), { type: 'warning' });
  } catch (error) {
    logger.warn('用户取消删除系统配置', error);
    return; // 用户主动取消删除操作
  }
  // 步骤2：执行删除 API（失败提示由 errorMessageResponseInterceptor 统一处理）
  try {
    if (row.id) await remove({ id: row.id });
    showToast.success(t('operationSuccess'));
    gridApi.query();
  } catch (error) {
    logger.warn('删除系统配置失败，详见拦截器提示', error);
    // 用户提示由 errorMessageResponseInterceptor 统一处理
  }
}

/** 处理列配置重置 */
function handleResetColumns() {
  resetToDefault();
  showToast.success(t('operationSuccess'));
}

/* 拖拽排序状态 */
const dragIndex = ref<number | null>(null);

function handleDragStart(index: number) {
  dragIndex.value = index;
}

function handleDragOver(event: DragEvent, index: number) {
  event.preventDefault();
  if (dragIndex.value === null || dragIndex.value === index) return;
  const newOrder = [...columnOrder.value];
  const [moved] = newOrder.splice(dragIndex.value, 1);
  newOrder.splice(index, 0, moved);
  columnOrder.value = newOrder;
  dragIndex.value = index;
}

function handleDragEnd() {
  dragIndex.value = null;
}
</script>

<template>
  <Page auto-content-height>
    <Grid :table-title="t('config')" role="grid" :aria-rowcount="gridApi.grid?.getTableData?.()?.tableData?.length ?? 0" :aria-label="t('config')">
      <template #toolbar-tools>
        <YdBadge v-if="dataScopeLabel" variant="destructive" style="margin-right: 8px" role="status" aria-live="polite">
          {{ dataScopeLabel }}
        </YdBadge>
        <YdButton aria-label="t('create')" v-permission="'sys:config:add'" @click="handleAdd">{{ t('create') }}</YdButton>
        <YdButton variant="outline" size="sm" class="ml-1" @click="columnConfigOpen = true" :aria-label="t('config')">
          <span class="mr-1">&#9881;</span>
          <span class="hidden sm:inline">列配置</span>
        </YdButton>
      </template>
    </Grid>
    <ConfigFormModal @success="gridApi.query()" />
    <ConfigHistoryDialog ref="historyDialogRef" @success="gridApi.query()" />

    <!-- 列配置弹窗 -->
    <Teleport to="body">
      <div
        v-if="columnConfigOpen"
        class="fixed inset-0 z-[60] flex items-center justify-center"
        role="dialog"
        aria-modal="true"
        :aria-label="t('config')"
      >
        <!-- 遮罩层 -->
        <div
          class="absolute inset-0 bg-black/50"
          @click="columnConfigOpen = false"
        />
        <!-- 面板 -->
        <div class="relative z-10 w-full max-w-lg rounded-lg bg-white p-6 shadow-xl">
          <div class="mb-4 flex items-center justify-between">
            <h2 class="text-lg font-semibold">列配置</h2>
            <YdButton variant="ghost" size="sm" @click="columnConfigOpen = false" aria-label="close">
              &times;
            </YdButton>
          </div>

          <div class="mb-4 max-h-96 space-y-2 overflow-y-auto">
            <div
              v-for="(field, index) in columnOrder"
              :key="field"
              class="flex items-center gap-3 rounded border p-2"
              draggable="true"
              @dragstart="handleDragStart(index)"
              @dragover="(e) => handleDragOver(e, index)"
              @dragend="handleDragEnd"
            >
              <!-- 拖拽手柄 -->
              <span class="cursor-grab select-none text-gray-400" title="拖拽排序">&#9776;</span>

              <!-- 可见性 checkbox -->
              <label class="flex flex-1 cursor-pointer items-center gap-2">
                <input
                  type="checkbox"
                  :checked="visibleColumns.includes(field)"
                  class="h-4 w-4"
                  @change="setColumnVisible(field, !visibleColumns.includes(field))"
                />
                <span>{{ columnLabels[field]?.() ?? field }}</span>
              </label>

              <!-- 列宽 slider -->
              <div class="flex items-center gap-2">
                <span class="text-xs text-gray-500">宽度</span>
                <input
                  type="range"
                  min="60"
                  max="400"
                  :value="columnWidth[field] ?? 150"
                  class="w-24"
                  @input="setColumnWidth(field, Number(($event.target as HTMLInputElement).value))"
                />
                <span class="w-10 text-right text-xs text-gray-500">{{ columnWidth[field] ?? 150 }}px</span>
              </div>
            </div>
          </div>

          <div class="flex justify-end gap-2">
            <YdButton variant="outline" size="sm" @click="handleResetColumns">重置为默认</YdButton>
            <YdButton size="sm" @click="columnConfigOpen = false">完成</YdButton>
          </div>
        </div>
      </div>
    </Teleport>
  </Page>
</template>
